<script>
 import Icon from './Icon.svelte';import {onMount} from 'svelte';import {invalidateAll} from '$app/navigation';
 let {children,section='overview',email='',preview=false}=$props();let open=$state(false);let refreshing=$state(false);let refreshFailed=$state(false);
 async function refresh(){if(preview||refreshing)return;refreshing=true;try{await invalidateAll();refreshFailed=false;}catch{refreshFailed=true;}finally{refreshing=false;}}
 onMount(()=>{if(preview)return;const interval=setInterval(()=>{if(document.visibilityState==='visible')refresh();},60000);return()=>clearInterval(interval);});
 const navigation=[['overview','Overview','overview'],['clients','Clients & access','account'],['nodes','Energy nodes','system'],['communities','Communities','home'],['health','System health','system'],['operations','Operations & enquiries','info'],['forecasting','Demand forecasting','history'],['sharing','Sharing policies','grid'],['settings','Settings & roles','lock'],['activity','Audit trail','history']];
 const link=s=>preview?'/admin-preview?view='+s:s==='overview'?'/admin':'/admin/'+s;
</script>
<svelte:window onkeydown={e=>{if(e.key==='Escape')open=false;}}/>
<div class="admin-frame"><a class="admin-skip" href="#admin-content">Skip to content</a><aside class:open class="admin-sidebar" id="admin-navigation"><a class="portal-brand" href="/"><img src="/gridubuntu-logo.png" alt=""/><span>GridUbuntu<small>OPERATIONS PLATFORM</small></span></a><div class="admin-nav-caption">WORKSPACE <span>Zimbabwe pilot</span></div><nav aria-label="Administrator navigation">{#each navigation as [key,label,icon]}<a href={link(key)} class:active={section===key} aria-current={section===key?'page':undefined} onclick={()=>open=false}><Icon name={icon} size={18}/><span>{label}</span>{#if section===key}<i></i>{/if}</a>{/each}</nav><div class="admin-sidebar-bottom"><div class="admin-purpose"><Icon name="sun" size={24}/><strong>Local sunshine.<br/>Collective strength.</strong><p>Build a clearer energy picture, one connection at a time.</p></div><span class="admin-identity"><span class="admin-avatar">GU</span><span><strong>{preview?'Design preview':'Administrator'}</strong><small>{email||'Illustrative workspace'}</small></span></span>{#if preview}<a class="admin-signout" href="/login">Back to sign-in →</a>{:else}<form method="POST" action="/logout"><button class="admin-signout"><Icon name="logout" size={15}/>Sign out</button></form>{/if}</div></aside>{#if open}<button class="admin-scrim" aria-label="Close navigation" onclick={()=>open=false}></button>{/if}<div class="admin-main"><header class="admin-topbar"><div><button class="admin-menu" aria-label="Toggle administrator navigation" aria-expanded={open} aria-controls="admin-navigation" onclick={()=>open=!open}><Icon name="menu"/></button><span>GRIDUBUNTU <b>/</b> OPERATIONS</span></div><div>{#if !preview}<button class="admin-refresh" onclick={refresh} disabled={refreshing} aria-label="Refresh administrator data"><Icon name="refresh" size={15}/><span>{refreshing?'Refreshing...':'Refresh data'}</span></button>{/if}<span class="admin-access-label"><Icon name="lock" size={14}/>{preview?'Sample workspace':'Administrator access'}</span><span class="admin-avatar">GU</span></div></header>{#if preview}<div class="preview-banner"><Icon name="info" size={17}/><span><strong>Admin design preview.</strong> Sample data only. Changes are disabled; the live admin platform requires your administrator login.</span><a href="/login">Sign in →</a></div>{/if}<main class="admin-content" id="admin-content">{#if refreshFailed}<div class="admin-notice failure" role="alert">Data could not refresh. Try again.</div>{/if}{@render children()}</main><footer class="admin-footer"><span>© {new Date().getFullYear()} GridUbuntu</span><span>Provider integrations are read only.</span><span>Harare time · CAT (UTC+2)</span></footer></div></div>
